package ar.gob.municipalidad.rentas;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

@Service
class BillingService {
    private final BillRepository bills; private final BillDebtRepository billDebts; private final DebtRepository debts; private final TaxpayerRepository taxpayers; private final CurrentIdentity identity;
    private final LiquidationRepository liquidations;private final AdjustmentRepository adjustments;private final LateChargeService lateCharges;private final FiscalProcessingDatePolicy dates;
    private final BillLifecycleService billLifecycle;
    private final BillPresentationStatusService billPresentation;
    BillingService(BillRepository bills,BillDebtRepository billDebts,DebtRepository debts,TaxpayerRepository taxpayers,CurrentIdentity identity,LiquidationRepository liquidations,AdjustmentRepository adjustments,LateChargeService lateCharges,FiscalProcessingDatePolicy dates,BillLifecycleService billLifecycle,BillPresentationStatusService billPresentation){this.bills=bills;this.billDebts=billDebts;this.debts=debts;this.taxpayers=taxpayers;this.identity=identity;this.liquidations=liquidations;this.adjustments=adjustments;this.lateCharges=lateCharges;this.dates=dates;this.billLifecycle=billLifecycle;this.billPresentation=billPresentation;}
    @Transactional Bill create(ApiDtos.CreateBillRequest request){return create(request,null);}
    @Transactional Bill create(ApiDtos.CreateBillRequest request,String key){
        String idempotencyKey=normalizeKey(key),fingerprint=idempotencyKey==null?null:fingerprint(request);
        TaxpayerReference taxpayer=(idempotencyKey==null?taxpayers.findById(request.taxpayerId()):taxpayers.findByIdForUpdate(request.taxpayerId())).orElseThrow(()->CatalogService.notFound("Contribuyente"));
        if(idempotencyKey!=null){Optional<Bill> existing=bills.findByTaxpayerIdAndIdempotencyKey(request.taxpayerId(),idempotencyKey);if(existing.isPresent()){if(!fingerprint.equals(existing.get().idempotencyFingerprint))throw new BusinessException("IDEMPOTENCY_KEY_REUSED","La clave de idempotencia ya fue utilizada con otro contenido",409);return existing.get();}}
        if(taxpayer.taxpayerType==TaxpayerType.ORGANIZATION)CatalogService.require(taxpayer.externalStatus==TaxpayerStatus.ACTIVA,"ORGANIZATION_NOT_ACTIVE","Sólo una organización activa puede emitir boletas");else CatalogService.require(taxpayer.externalStatus!=TaxpayerStatus.BLOCKED,"TAXPAYER_BLOCKED","No se pueden emitir nuevas boletas para un contribuyente bloqueado");CatalogService.require(!request.dueDate().isBefore(LocalDate.now()),"INVALID_BILL_DUE_DATE","El vencimiento no puede estar en el pasado");List<Long> unique=request.debtIds().stream().distinct().toList();CatalogService.require(unique.size()==request.debtIds().size(),"DUPLICATE_BILL_DEBT","La boleta contiene deudas repetidas");List<Debt> selected=billLifecycle.lockForIssue(unique);CatalogService.require(selected.stream().allMatch(x->x.taxpayerId.equals(request.taxpayerId())),"BILL_TAXPAYER_MISMATCH","Todas las deudas deben pertenecer al contribuyente");CatalogService.require(selected.stream().allMatch(Debt::isCollectible),"DEBT_NOT_BILLABLE","La boleta contiene una deuda no exigible");billLifecycle.requireNoIssuedBill(unique);Bill bill=new Bill();bill.number="BILL-"+UUID.randomUUID();bill.taxpayerId=request.taxpayerId();bill.idempotencyKey=idempotencyKey;bill.idempotencyFingerprint=fingerprint;bill.totalAmount=MonetaryAmounts.normalize(selected.stream().map(x->x.outstandingBalance).reduce(BigDecimal.ZERO,BigDecimal::add));bill.issueDate=LocalDate.now();bill.dueDate=request.dueDate();bill.status=BillStatus.ISSUED;bill.createdBy=identity.get().userId();bill.createdAt=OffsetDateTime.now();bills.save(bill);for(Debt debt:selected){BillDebt link=new BillDebt();link.billId=bill.id;link.debtId=debt.id;link.amountAtIssue=debt.outstandingBalance;billDebts.save(link);}return bill;
    }
    private String normalizeKey(String value){if(value==null)return null;String normalized=value.trim();if(!normalized.matches("[A-Za-z0-9._:-]{1,128}"))throw new BusinessException("INVALID_IDEMPOTENCY_KEY","Idempotency-Key debe contener entre 1 y 128 caracteres alfanuméricos, punto, guion, guion bajo o dos puntos",400);return normalized;}
    private String fingerprint(ApiDtos.CreateBillRequest request){try{String canonical=request.taxpayerId()+"\n"+request.dueDate()+"\n"+request.debtIds().stream().map(String::valueOf).sorted().collect(java.util.stream.Collectors.joining(","));return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException ex){throw new IllegalStateException("SHA-256 no disponible",ex);}}
    ApiDtos.BillDetail detail(Long id){Bill bill=bills.findById(id).orElseThrow(()->CatalogService.notFound("Boleta"));identity.requireOwnership(bill.taxpayerId);List<BillDebt> links=billDebts.findByBillIdOrderByIdAsc(id);return new ApiDtos.BillDetail(bill,links,billPresentation.forBill(bill,links));}
    @Transactional(readOnly=true) ApiDtos.BillDetailResponse pricingDetail(Long id){ApiDtos.BillDetail source=detail(id);Bill bill=source.bill();List<BillDebt> links=source.debts();List<Long> debtIds=links.stream().map(x->x.debtId).toList();Map<Long,Debt> debtById=debts.findAllById(debtIds).stream().collect(java.util.stream.Collectors.toMap(x->x.id,x->x));List<Long> liquidationIds=debtById.values().stream().filter(x->x.originType==DebtOriginType.LIQUIDATION&&x.liquidationId!=null).map(x->x.liquidationId).distinct().toList();Map<Long,Liquidation> liquidationById=liquidations.findAllById(liquidationIds).stream().collect(java.util.stream.Collectors.toMap(x->x.id,x->x));Map<Long,List<AdjustmentRequest>> adjustmentsByDebt=adjustments.findByDebtIdInAndStatusAndResolvedAtAfter(debtIds,AdjustmentStatus.APPROVED,bill.createdAt).stream().collect(java.util.stream.Collectors.groupingBy(x->x.debtId));LocalDate calculationDate=dates.today();Map<Long,FiscalProcessingController.LateChargeResponse> pending=lateCharges.previewIfApplicable(debtById.values(),calculationDate);List<ApiDtos.BillDebtPricingResponse> pricing=new ArrayList<>();BigDecimal total=zero();for(BillDebt link:links){Debt debt=Optional.ofNullable(debtById.get(link.debtId)).orElseThrow(()->CatalogService.notFound("Deuda"));Liquidation liquidation=debt.liquidationId==null?null:liquidationById.get(debt.liquidationId);BigDecimal discount=zero(),surcharge=zero(),interest=zero(),correction=zero();for(AdjustmentRequest adjustment:adjustmentsByDebt.getOrDefault(debt.id,List.of()))switch(adjustment.type){case DISCOUNT->discount=discount.add(adjustment.amount);case SURCHARGE->surcharge=surcharge.add(adjustment.amount);case INTEREST->interest=interest.add(adjustment.amount);case CORRECTION->correction=correction.add(adjustment.newDebtAmount.subtract(adjustment.previousDebtAmount));}FiscalProcessingController.LateChargeResponse quote=pending.get(debt.id);BigDecimal pendingSurcharge=quote==null?zero():quote.surchargeAmount(),pendingInterest=quote==null?zero():quote.interestAmount();BigDecimal payable=money(debt.outstandingBalance.add(pendingSurcharge).add(pendingInterest));pricing.add(new ApiDtos.BillDebtPricingResponse(debt.id,link.amountAtIssue,debt.currentAmount,debt.outstandingBalance,liquidation==null?zero():liquidation.discountAmount,liquidation==null?zero():liquidation.exemptionAmount,liquidation==null?zero():liquidation.surchargeAmount,liquidation==null?zero():liquidation.interestAmount,money(discount),money(surcharge),money(interest),money(correction),pendingSurcharge,pendingInterest,payable));total=total.add(payable);}ApiDtos.BillResponse snapshot=ApiResponses.of(bill,links,source.presentationStatus());return new ApiDtos.BillDetailResponse(snapshot.id(),snapshot.number(),snapshot.taxpayerId(),snapshot.totalAmount(),snapshot.issueDate(),snapshot.dueDate(),snapshot.status(),snapshot.cancellationReason(),snapshot.expired(),snapshot.createdBy(),snapshot.createdAt(),snapshot.debts(),snapshot.presentationStatus(),money(total),OffsetDateTime.now(),pricing);}
    private BigDecimal zero(){return MonetaryAmounts.zero();}
    private BigDecimal money(BigDecimal value){return MonetaryAmounts.normalize(value);}
}
